import io
from reportlab.lib import colors
from reportlab.lib.pagesizes import letter
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import inch
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle

# UC-08: "Generated report shall include: User symptom input, Extracted
# symptoms, Predicted diseases, Confidence scores, Explainable AI reasoning,
# Model name, Model version, Medical disclaimer."
DISCLAIMER = (
    "This report is generated by an educational coursework prototype and is not a "
    "medical device. It does not constitute a medical diagnosis and must not be used "
    "as a substitute for professional medical advice. Please consult a qualified "
    "healthcare provider for any health concerns."
)

styles = getSampleStyleSheet()
_heading = ParagraphStyle("ReportHeading", parent=styles["Heading2"], spaceBefore=14, spaceAfter=6)
_body = styles["BodyText"]


def generate_diagnosis_pdf(diagnosis, patient_name=""):
    """
    Builds a single-page PDF report for a DiagnosisHistory record and
    returns the raw PDF bytes.
    """
    buffer = io.BytesIO()
    doc = SimpleDocTemplate(buffer, pagesize=letter, topMargin=0.75 * inch, bottomMargin=0.75 * inch)
    predictions = diagnosis.predictions or {}
    ranked = predictions.get("rankedPredictions") or [
        {"disease": predictions.get("disease"), "confidence": predictions.get("confidence")}
    ]
    factors = predictions.get("influentialFactors") or []

    story = [
        Paragraph("AI-Based Medical Diagnosis System — Diagnosis Report", styles["Title"]),
        Spacer(1, 4),
        Paragraph(f"Generated: {diagnosis.prediction_timestamp.strftime('%Y-%m-%d %H:%M')}", _body),
    ]
    if patient_name:
        story.append(Paragraph(f"Patient: {patient_name}", _body))

    story.append(Paragraph("Symptom Input", _heading))
    story.append(Paragraph(diagnosis.input_text, _body))

    story.append(Paragraph("Extracted Symptoms", _heading))
    symptoms = ", ".join(s.replace("_", " ") for s in (diagnosis.extracted_symptoms or [])) or "None mapped"
    story.append(Paragraph(symptoms, _body))
    story.append(Paragraph(f"Reported severity: {diagnosis.severity} | Reported duration: {diagnosis.duration}", _body))

    story.append(Paragraph("Predicted Diseases and Confidence Scores", _heading))
    rows = [["Disease", "Confidence"]] + [
        [r.get("disease", ""), f"{r.get('confidence', '')}%"] for r in ranked
    ]
    table = Table(rows, colWidths=[3.5 * inch, 1.5 * inch])
    table.setStyle(TableStyle([
        ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#0f172a")),
        ("TEXTCOLOR", (0, 0), (-1, 0), colors.white),
        ("GRID", (0, 0), (-1, -1), 0.5, colors.grey),
        ("FONTSIZE", (0, 0), (-1, -1), 9),
        ("BOTTOMPADDING", (0, 0), (-1, -1), 6),
        ("TOPPADDING", (0, 0), (-1, -1), 6),
    ]))
    story.append(table)

    story.append(Paragraph("Explainable AI Reasoning", _heading))
    if predictions.get("explanationText"):
        story.append(Paragraph(predictions["explanationText"], _body))
    elif factors:
        for f in factors:
            story.append(Paragraph(f"- {f.get('name', '').replace('_', ' ')} → impact score {f.get('impact')}", _body))
    else:
        story.append(Paragraph("No influential factors were available for this prediction.", _body))

    applied_rule = predictions.get("appliedRule") if isinstance(predictions.get("appliedRule"), dict) else None
    if applied_rule:
        story.append(Paragraph("Expert Rule Adjustment", _heading))
        story.append(Paragraph(
            f"Condition \"{applied_rule.get('condition')}\" triggered action \"{applied_rule.get('action')}\" "
            f"(priority {applied_rule.get('priority')}).", _body,
        ))

    story.append(Paragraph("Model Information", _heading))
    story.append(Paragraph(f"Model name: {diagnosis.model_name} | Model version: {diagnosis.model_version}", _body))

    story.append(Paragraph("Medical Disclaimer", _heading))
    story.append(Paragraph(DISCLAIMER, ParagraphStyle("Disclaimer", parent=_body, textColor=colors.HexColor("#b91c1c"))))

    doc.build(story)
    return buffer.getvalue()
